  uint8_t  version;         // 1
  uint8_t  msgType;         // 3=presence
  uint32_t seq;             // current config seq (or 0 if no session)
  uint8_t  present;         // 0/1 (effective presence for cube)
  uint16_t distCm;          // 0 if unknown
};

struct BeaconSuccessMsg {
  char     magic[4];        // "ROOS"
  uint8_t  version;         // 1
  uint8_t  msgType;         // 4=success
  uint32_t seq;             // current config seq
};

struct BeaconStopMsg {
  char     magic[4];        // "ROOS"
  uint8_t  version;         // 1
  uint8_t  msgType;         // 5=stop
  uint32_t seq;             // session/config seq to stop
};

