message_layouts.text:
struct BeaconCfgMsg {
  char     magic[4];        // "ROOS"
  roos_u8  version;         // 1
  roos_u8  msgType;         // 1=config
  roos_u8  distHalfFt;      // 1..16 (0.5..8.0 ft)
  roos_u8  timeHalfMin;     // 1..10 (0.5..5.0 min)
  roos_u32 seq;             // incrementing
};

struct BeaconAckMsg {
  char     magic[4];
  roos_u8  version;
  roos_u8  msgType;         // 2=ack
  roos_u32 seq;             // echoes config seq
  roos_u8  ok;              // 1=accepted, 0=bad
};

struct BeaconPresenceMsg {
  char     magic[4];
  roos_u8  version;
  roos_u8  msgType;         // 3=presence
  roos_u32 seq;             // current config seq (or 0 if none yet)
  roos_u8  present;         // 0/1
  roos_u16 distCm;          // 0 if unknown
};

struct BeaconSuccessMsg {
  char     magic[4];
  roos_u8  version;
  roos_u8  msgType;         // 4=success
  roos_u32 seq;             // current config seq
};

struct BeaconStopMsg {
  char     magic[4];
  roos_u8  version;
  roos_u8  msgType;         // 5=stop
  roos_u32 seq;             // session/config seq to stop
};

